use crate::*;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,turn:RetainedWorkOutcome)->RetainedCloneProgress{*fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(*bank));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;p}
#[derive(crate::NativeReceive,crate::RetireOwned)]#[value(crate="crate")]struct InitializerRow{value:u64}
fn initializer<T:crate::owned::NativeReceive<crate::DslValue>>(bank:&mut RetainedCloneGrant,fuel:&mut u64){use crate::owned::NativeReceiver;let(mut receiver,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||T::receiver());assert_eq!(heap,(0,0));receiver.begin_close();let mut actual=None;for _ in 0..10000{if receiver.terminal_is_empty()&&actual.is_none(){return}let turn=crate::source_fixture::close_step(&mut actual,RetainedCloneGrant{maximum_items:1,..*bank},*fuel,receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a));post(bank,fuel,turn);}panic!("actual pure receiver initializer cleanup exhausted finite turns")}
#[test]fn actual_concrete_and_derived_receiver_initializers_allocate_no_backing(){let row:serde_json::Value=serde_json::from_str(include_str!("../../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();initializer::<u64>(&mut bank,&mut fuel);initializer::<String>(&mut bank,&mut fuel);initializer::<Option<u64>>(&mut bank,&mut fuel);initializer::<Vec<u64>>(&mut bank,&mut fuel);initializer::<[u64;2]>(&mut bank,&mut fuel);initializer::<InitializerRow>(&mut bank,&mut fuel);initializer::<(u64,String)>(&mut bank,&mut fuel);assert_eq!(row["pureInitializers"].as_array().unwrap().len(),7);}
